package com.xyz.question_bank_management_system.modules.dialogue.mapper;
import com.xyz.question_bank_management_system.modules.dialogue.entity.*; import org.apache.ibatis.annotations.*; import java.util.List;
@Mapper public interface DialogueMapper { @Insert("INSERT INTO dialogue_session(user_id,title,session_type,status,target_goal_id,started_at,last_message_at,created_at,updated_at) VALUES(#{userId},#{title},#{sessionType},#{status},#{targetGoalId},NOW(3),NOW(3),NOW(3),NOW(3))") @Options(useGeneratedKeys=true,keyProperty="id") int insertSession(DialogueSession s); @Select("SELECT * FROM dialogue_session WHERE id=#{id} AND user_id=#{userId}") DialogueSession ownedSession(@Param("id") Long id,@Param("userId") Long userId); @Select("SELECT * FROM dialogue_session WHERE user_id=#{userId} ORDER BY last_message_at DESC,id DESC") List<DialogueSession> sessions(@Param("userId") Long userId); @Insert("INSERT INTO dialogue_message(session_id,user_id,role,content,reply_to_message_id,llm_call_id,profile_extracted,created_at) VALUES(#{sessionId},#{userId},#{role},#{content},#{replyToMessageId},#{llmCallId},#{profileExtracted},NOW(3))") @Options(useGeneratedKeys=true,keyProperty="id") int insertMessage(DialogueMessage m); @Select("SELECT * FROM dialogue_message WHERE session_id=#{sessionId} ORDER BY created_at,id") List<DialogueMessage> messages(@Param("sessionId") Long sessionId); @Update("UPDATE dialogue_session SET last_message_at=NOW(3),updated_at=NOW(3) WHERE id=#{id}") int touch(@Param("id") Long id); }
